<script setup>
import{computed,onMounted,ref}from'vue';import{Box,CheckCircle2,CircleAlert,Download,FileKey2,PackageCheck,Power,ShieldCheck}from'@lucide/vue';import{getPlugin,installPlugin,listPlugins,uninstallPlugin}from'../api'
const items=ref([]),selected=ref(null),loading=ref(true),busy=ref(false),error=ref('');const role=localStorage.getItem('edumatrix_role')||'student';const canManage=computed(()=>role==='admin')
function msg(e,f){const d=e?.response?.data?.detail;return d?.message||e?.message||f}async function load(){loading.value=true;error.value='';try{items.value=(await listPlugins()).items;if(items.value.length){const installed=items.value.find(x=>x.registration_id);selected.value=installed?await getPlugin(installed.plugin_id):items.value[0]}}catch(e){error.value=msg(e,'插件注册表加载失败')}finally{loading.value=false}}
async function install(row){busy.value=true;error.value='';try{selected.value=await installPlugin(row.plugin_id);await refreshItems()}catch(e){error.value=msg(e,'安装失败')}finally{busy.value=false}}
async function disable(){busy.value=true;error.value='';try{selected.value=await uninstallPlugin(selected.value.plugin_id,selected.value.lock_version);await refreshItems()}catch(e){error.value=msg(e,'卸载失败')}finally{busy.value=false}}
async function refreshItems(){items.value=(await listPlugins()).items}async function choose(row){selected.value=row.registration_id?await getPlugin(row.plugin_id):row}
onMounted(load)
</script>
<template><main class="plugins" data-testid="plugin-registry"><header><div><p>GOVERNED DATA PLUGINS</p><h1>领域插件注册中心</h1><span>只安装作品内预置的纯数据插件；逐文件校验 hash，不执行第三方代码。</span></div><div class="trust"><ShieldCheck :size="19"/><b>零网络 · 零密钥 · 零代码执行</b></div></header><p v-if="error" class="notice err"><CircleAlert :size="15"/>{{error}}</p><p v-if="loading" class="notice">正在验证预置插件...</p><div v-else class="layout"><aside><button v-for="row in items" :key="row.plugin_id" :class="{active:selected?.plugin_id===row.plugin_id}" @click="choose(row)"><Box :size="17"/><span><b>{{row.title}}</b><small>{{row.plugin_version}} · {{row.status}}</small></span></button></aside><section v-if="selected" class="detail"><div class="title"><div><h2>{{selected.title}}</h2><p>{{selected.domain_key}} · {{selected.plugin_id}}</p></div><span :class="selected.status">{{selected.status}}</span></div><div class="facts"><article><FileKey2 :size="16"/><span>包完整性</span><code>{{selected.package_hash?.slice(0,16)}}...</code></article><article><PackageCheck :size="16"/><span>许可证</span><b>{{selected.license}}</b></article><article><ShieldCheck :size="16"/><span>能力边界</span><b>{{selected.allowed_actions?.join(' / ')}}</b></article></div><section class="source"><h3>来源与署名</h3><p>{{selected.attribution}}</p><a :href="selected.source_url" target="_blank" rel="noreferrer">{{selected.source_url}}</a><small>{{selected.source_version}}</small></section><div v-if="canManage" class="actions"><button v-if="selected.status!=='installed'" :disabled="busy" @click="install(selected)"><Download :size="15"/>验证并安装</button><button v-else class="danger" :disabled="busy" @click="disable"><Power :size="15"/>禁用并保留历史</button></div><p v-else class="readonly">普通用户可核对插件来源与能力边界，安装和卸载仅由管理员执行。</p><section v-if="selected.verification" class="verified"><CheckCircle2 :size="18"/><div><h3>校验通过</h3><p>{{selected.verification.verified_assets.length}} 个资产 · {{selected.verification.package_hash}}</p></div></section><section v-if="selected.events?.length" class="events"><h3>生命周期记录</h3><div v-for="event in selected.events" :key="event.id"><b>{{event.action}} · {{event.outcome}}</b><span>{{event.reason}}</span></div></section></section></div></main></template>
<style scoped>.plugins{max-width:1120px;margin:0 auto;color:#26322b}.plugins header{display:flex;justify-content:space-between;gap:20px;padding-bottom:20px;border-bottom:1px solid #d9e1dc}.plugins header p{margin:0;color:#4c6e59;font-size:10px;font-weight:800}.plugins h1{margin:6px 0;font-size:24px;letter-spacing:0}.plugins header span{color:#6d786f;font-size:12px}.trust{display:flex;align-items:center;gap:8px;padding:12px;border:1px solid #c7dccd;background:#f1f7f3;color:#386047;font-size:10px}.notice{display:flex;gap:7px;padding:10px;background:#f3f6f4}.err{background:#fff0ed;color:#8c4339}.layout{display:grid;grid-template-columns:240px 1fr;gap:14px;margin-top:16px}.layout aside,.detail{border:1px solid #d9e1dc;background:#fff}.layout aside{padding:10px}.layout aside button{display:flex;width:100%;gap:9px;padding:12px 8px;text-align:left;border:0;border-bottom:1px solid #e8ece9;background:#fff}.layout aside button.active{background:#f0f6f2}.layout aside span,.layout aside b,.layout aside small{display:block}.layout aside b{font-size:11px}.layout aside small{margin-top:4px;color:#79847c;font-size:8px}.detail{padding:18px}.title{display:flex;justify-content:space-between;border-bottom:1px solid #e2e7e3;padding-bottom:12px}.title h2{margin:0;font-size:17px}.title p{margin:4px 0 0;color:#79847c;font-size:9px}.title>span{height:max-content;padding:4px 7px;background:#f3f5f3;font-size:9px}.title>span.installed{background:#eaf6ee;color:#316445}.title>span.disabled{background:#fff0ed;color:#8a453c}.facts{display:grid;grid-template-columns:repeat(3,1fr);margin-top:14px;border:1px solid #e0e6e2}.facts article{display:grid;grid-template-columns:auto 1fr;gap:3px 8px;padding:12px;border-right:1px solid #e0e6e2}.facts article:last-child{border:0}.facts svg{grid-row:1/3}.facts span{font-size:8px;color:#7d877f}.facts b,.facts code{font-size:9px;overflow-wrap:anywhere}.source,.events{margin-top:14px;padding:13px;background:#f7f9f7}.source h3,.events h3,.verified h3{margin:0;font-size:11px}.source p,.source a,.source small{display:block;margin:5px 0 0;font-size:9px;overflow-wrap:anywhere}.source a{color:#396b51}.actions{display:flex;margin-top:14px}.actions button{display:flex;align-items:center;gap:6px;min-height:34px;padding:0 11px;border:0;background:#3f694e;color:#fff}.actions .danger{background:#8e4a40}.readonly{padding:10px;background:#f4f6f4;font-size:9px}.verified{display:flex;gap:9px;margin-top:14px;padding:12px;border:1px solid #c9dfd0;background:#f0f8f2;color:#315f40}.verified p{margin:4px 0 0;font-size:8px;overflow-wrap:anywhere}.events>div{display:flex;justify-content:space-between;gap:8px;padding:8px 0;border-bottom:1px solid #e2e7e3;font-size:8px}.events span{text-align:right}@media(max-width:760px){.plugins header{flex-direction:column}.layout{grid-template-columns:1fr}.facts{grid-template-columns:1fr}.facts article{border-right:0;border-bottom:1px solid #e0e6e2}.layout aside{display:flex;overflow:auto}.layout aside button{min-width:200px}.title{gap:8px}.events>div{flex-direction:column}.events span{text-align:left}}</style>
